/*	Build the attendee QR page (fully self-contained: QR library is inlined, no external calls).	*/

const webhook_obj = $('QR Page (Webhook)').item.json;
const query_obj = (webhook_obj && webhook_obj.query) ? webhook_obj.query : {};
const cfg_obj = $('Config').item.json;
const eventId_str = String(query_obj.eventId || '').trim();
const title_str = String(query_obj.title || cfg_obj.TITLE || '').trim();
const header_str = String(query_obj.header || cfg_obj.HEADER || '').trim();
const body_str = String(cfg_obj.BODY || '');
const footer_str = String(cfg_obj.FOOTER || '');
const baseUrl_str = String(cfg_obj.BASE_URL || '').trim();
const altText_str = String(cfg_obj.ALT_TEXT || 'Attendance QR code');
const logo_str = String(cfg_obj.LOGO || '');
let qrText_str = baseUrl_str;
if (eventId_str !== '')
{
	qrText_str = baseUrl_str + (baseUrl_str.indexOf('?') > -1 ? '&' : '?') + 'eventId=' + encodeURIComponent(eventId_str);
}
function esc_str(v_var)
{
	return String(v_var == null ? '' : v_var).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function nl2br_str(v_str)
{
	return esc_str(v_str).replace(/\r\n|\r|\n/g, '<br>');
}
function contrastText_str(hex_str)
{
	const m_var = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(String(hex_str || '').trim());
	if (!m_var)
	{
		return '#ffffff';
	}
	const r_num = parseInt(m_var[1], 16);
	const g_num = parseInt(m_var[2], 16);
	const b_num = parseInt(m_var[3], 16);
	const lum_num = (0.299 * r_num + 0.587 * g_num + 0.114 * b_num) / 255;
	return lum_num > 0.6 ? '#1f1f1f' : '#ffffff';
}
const bannerText_str = contrastText_str(accent_str);
const css_str = [
	'*{box-sizing:border-box;}',
	'body{margin:0;background:#f4f4f5;}',
	'.qrp-body-wrap{font-family:Arial,Helvetica,sans-serif;color:#1f1f1f;display:flex;align-items:center;justify-content:center;min-height:100vh;padding:clamp(1rem,4vw,2.5rem);}',
	'.qrp-card{width:100%;max-width:34rem;background:#fff;border:1px solid #e2e2e2;border-radius:1rem;overflow:hidden;text-align:center;box-shadow:0 .5rem 2rem rgba(0,0,0,.08);}',
	'.qrp-banner{background:' + accent_str + ';border-bottom:.25rem solid ' + border_str + ';padding:clamp(1.1rem,4vw,1.9rem) clamp(1rem,4vw,1.75rem);}',
	'.qrp-title{margin:0;color:' + bannerText_str + ';font-size:clamp(1.4rem,5vw,2rem);letter-spacing:.02em;}',
	'.qrp-sub{margin:.5rem 0 0;color:' + bannerText_str + ';opacity:.92;font-size:clamp(.95rem,3vw,1.15rem);line-height:1.4;}',
	'.qrp-qrwrap{padding:clamp(1.25rem,5vw,2.25rem) clamp(1rem,4vw,2rem) clamp(.75rem,3vw,1.25rem);display:flex;justify-content:center;}',
	'.qrp-qr{position:relative;width:clamp(13rem,60vw,22rem);height:auto;aspect-ratio:1/1;}',
	'.qrp-qr #qrp-target{width:100%;height:100%;}',
