/*	  &sessionId=<id>              One code, that session only. Implies session mode.	*/
/*	  &date=YYYY-MM-DD             Codes for sessions on that local date. Implies session mode.	*/
/*	  &from=YYYY-MM-DD             Codes from that date onward. Implies session mode.	*/
/*	  &to=YYYY-MM-DD               Codes up to that date. Combine with from for a span.	*/
/*	Config QR_MODE 'session' (the default) prints one code per session. Setting QR_MODE to 'event'	*/
/*	switches to a single per-event code. Dates are compared in each session's OWN timezone,	*/
/*	not the server's.	*/

let html_str = String($json.html || '');
const cfg_obj = $('Config').item.json;
const webhook_obj = $('QR Page (Webhook)').item.json;
const query_obj = (webhook_obj && webhook_obj.query) ? webhook_obj.query : {};
const eventId_str = String($json.eventId || '').trim();
const baseUrl_str = String(cfg_obj.BASE_URL || '').trim();
const logo_str = String(cfg_obj.LOGO || '');

function esc_str(v_var)
{
	return String(v_var == null ? '' : v_var).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/*	One styled page used for every refusal, so they all look like the same system.	*/
function messagePage_str(heading_str, paragraphs_ary)
{
	let body_str = '';
	for (const paragraph_str of paragraphs_ary)
	{
		body_str += '<p>' + paragraph_str + '</p>';
	}
	return '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">'
		+ '<meta name="viewport" content="width=device-width, initial-scale=1.0">'
		+ '<title>' + esc_str(heading_str) + '</title><style>'
		+ '*{box-sizing:border-box;}body{margin:0;background:#f4f4f5;font-family:Arial,Helvetica,sans-serif;color:#1f1f1f;}'
		+ '.nq-wrap{display:flex;align-items:center;justify-content:center;min-height:100vh;padding:clamp(1rem,4vw,2.5rem);}'
		+ '.nq-card{width:100%;max-width:34rem;background:#fff;border:1px solid #e2e2e2;border-radius:1rem;overflow:hidden;box-shadow:0 .5rem 2rem rgba(0,0,0,.08);}'
		+ '.nq-banner{background:#1f2937;border-bottom:.25rem solid #2563eb;padding:clamp(1.1rem,4vw,1.9rem) clamp(1rem,4vw,1.75rem);text-align:center;}'
		+ '.nq-banner h1{margin:0;color:#fff;font-size:clamp(1.3rem,5vw,1.8rem);}'
		+ '.nq-body{padding:clamp(1.25rem,5vw,2rem);line-height:1.6;color:#3c3c3c;}'
		+ '.nq-body p{margin:0 0 1rem;}.nq-body p:last-child{margin-bottom:0;}'
		+ 'code{background:#f4f4f5;padding:.15rem .35rem;border-radius:.25rem;font-size:.95em;word-break:break-all;}'
		+ '</style></head><body><div class="nq-wrap"><main class="nq-card">'
		+ '<header class="nq-banner"><h1>' + esc_str(heading_str) + '</h1></header>'
		+ '<div class="nq-body">' + body_str + '</div></main></div></body></html>';
}

/*	=== 1. No event id ===	*/
/*	Build QR Page falls back to the bare BASE_URL when eventId is empty, which yields a perfectly	*/
/*	scannable code that checks nobody in and looks identical to a good one once printed.	*/
if (eventId_str === '')
{
	const msg_str = messagePage_str('No event selected', [
		'This page was opened without an event, so no QR code has been produced.',
		'A code generated without an event would still scan, but it would check nobody in, and once printed it would look exactly like a working one. So it is deliberately not shown.',
		'Add <code>?eventId=&lt;Administrate event id&gt;</code> to the address of this page, or generate the link from the URL Generator, which fills it in for you.'
	]);
	return [{ json: { html: msg_str, qrText: '', eventId: '', refused: 'no-event-id' } }];
}

/*	=== 2. Which sessions, if any ===	*/
const sessionIdFilter_str = String(query_obj.sessionId || '').trim();
const dateFilter_str = String(query_obj.date || '').trim();
const fromFilter_str = String(query_obj.from || '').trim();
const toFilter_str = String(query_obj.to || '').trim();
const hasFilter_bln = (sessionIdFilter_str !== '' || dateFilter_str !== '' || fromFilter_str !== '' || toFilter_str !== '');

/*	Any filter implies session mode; asking for one session and getting the event code would be worse	*/
/*	than useless, because the two look identical once printed.	*/
const mode_str = hasFilter_bln ? 'session' : String(query_obj.mode || cfg_obj.QR_MODE || 'event').trim().toLowerCase();

let eventTitle_str = '';
let sessions_ary = [];
try
{
	const event_obj = $('Fetch Event').item.json.data.events.edges[0].node;
	eventTitle_str = String(event_obj.title || '').trim();
	sessions_ary = (event_obj.sessions && event_obj.sessions.edges) ? event_obj.sessions.edges.map(function (edge_obj) { return edge_obj.node; }) : [];
} catch (error) {}

function localDate_str(session_obj)
{
	return String(session_obj.timeZonedStart || session_obj.start || '').slice(0, 10);
}

/*	ISO dates compare correctly as plain strings, so no Date objects are needed for the range test.	*/
function matchesFilter_bln(session_obj)
{
	if (sessionIdFilter_str !== '')
	{
		return String(session_obj.id) === sessionIdFilter_str;
	}
	const date_str = localDate_str(session_obj);
	if (dateFilter_str !== '')
	{
		return date_str === dateFilter_str;
	}
	if (fromFilter_str !== '' && date_str < fromFilter_str)
	{
		return false;
	}
	if (toFilter_str !== '' && date_str > toFilter_str)
	{
		return false;
	}
	return true;
}

let chosen_ary = sessions_ary.slice();
chosen_ary.sort(function (a_obj, b_obj)
{
	return String(a_obj.timeZonedStart || a_obj.start || '').localeCompare(String(b_obj.timeZonedStart || b_obj.start || ''));
});

if (mode_str === 'session' && hasFilter_bln)
{
	chosen_ary = chosen_ary.filter(matchesFilter_bln);
}

/*	A filter that matches nothing must say so. Falling back to the event code here would hand someone	*/
/*	a code for a different session than the one they asked for, with nothing on the page to show it.	*/
if (hasFilter_bln && chosen_ary.length === 0)
{
	let asked_str = '';
	if (sessionIdFilter_str !== '') { asked_str = 'session <code>' + esc_str(sessionIdFilter_str) + '</code>'; }
	else if (dateFilter_str !== '') { asked_str = 'the date <code>' + esc_str(dateFilter_str) + '</code>'; }
	else { asked_str = 'that date range'; }

	const msg_str = messagePage_str('No matching sessions', [
		'This event has ' + sessions_ary.length + ' session' + (sessions_ary.length === 1 ? '' : 's') + ', and none of them match ' + asked_str + '.',
		'No code has been produced, because a code for the wrong session looks identical to the right one once printed.',
		'Check the filter, or drop it and use <code>&amp;mode=session</code> to see every session on this event.'
	]);
	return [{ json: { html: msg_str, qrText: '', eventId: eventId_str, refused: 'no-matching-sessions' } }];
}

const wantSessions_bln = (mode_str === 'session' && chosen_ary.length > 0);

function truthy_bln(v_var, default_bln) { if (v_var === undefined || v_var === null || v_var === '') { return default_bln; } if (typeof v_var === 'boolean') { return v_var; } const s_str = String(v_var).trim().toLowerCase(); return !(s_str === 'false' || s_str === '0' || s_str === 'no' || s_str === 'off'); }
const time24_bln = truthy_bln(cfg_obj.TIME_24H, false);

function parseLocal_obj(tz_str) { const s_str = String(tz_str || ''); if (s_str.length < 16) { return null; } const y_int = parseInt(s_str.slice(0, 4), 10), mo_int = parseInt(s_str.slice(5, 7), 10), da_int = parseInt(s_str.slice(8, 10), 10), hh_int = parseInt(s_str.slice(11, 13), 10), mi_int = parseInt(s_str.slice(14, 16), 10); if (isNaN(y_int) || isNaN(mo_int) || isNaN(da_int)) { return null; } return { y: y_int, mo: mo_int, da: da_int, hh: hh_int, mi: mi_int }; }

function pad_str(n_int)
{
	return (n_int < 10 ? '0' : '') + n_int;
}

function tm_str(h_int, m_int)
{
	if (time24_bln)
	{
		return pad_str(h_int) + ':' + pad_str(m_int);
	}
	let h12_int = h_int % 12;
	if (h12_int === 0)
	{
		h12_int = 12;
	}
	return h12_int + ':' + pad_str(m_int) + (h_int < 12 ? 'am' : 'pm');
}

function dateLabel_str(parts_obj)
{
	const date_var = new Date(Date.UTC(parts_obj.y, parts_obj.mo - 1, parts_obj.da, parts_obj.hh, parts_obj.mi));
	function part_str(options_obj)
	{
		try
		{
			return new Intl.DateTimeFormat('en-GB', Object.assign({ timeZone: 'UTC' }, options_obj)).format(date_var);
		} catch (error) {
			return '';
		}
	}
	let label_str = part_str({ weekday: 'short' }) + ' ' + parts_obj.da + ' ' + part_str({ month: 'short' }) + ' ' + parts_obj.y;
	if (label_str.indexOf('undefined') > -1)
	{
		label_str = parts_obj.y + '-' + pad_str(parts_obj.mo) + '-' + pad_str(parts_obj.da);
	}
	return label_str;
}

/*	A session running across midnight must show its end DATE as well, or a multi-day session reads as	*/
/*	'9:00am - 8:59am' and appears to finish before it started.	*/
function fmtRange_str(startTZ_str, endTZ_str)
{
	const start_obj = parseLocal_obj(startTZ_str);
	if (!start_obj)
	{
		return '';
	}
	let out_str = dateLabel_str(start_obj) + ', ' + tm_str(start_obj.hh, start_obj.mi);
	const end_obj = parseLocal_obj(endTZ_str);
	if (end_obj)
	{
		const sameDay_bln = (start_obj.y === end_obj.y && start_obj.mo === end_obj.mo && start_obj.da === end_obj.da);
		if (sameDay_bln)
		{
			out_str += ' - ' + tm_str(end_obj.hh, end_obj.mi);
		} else {
			out_str += ' - ' + dateLabel_str(end_obj) + ', ' + tm_str(end_obj.hh, end_obj.mi);
		}
	}
	return out_str;
}

function buildUrl_str(sessionId_str)
{
	let url_str = baseUrl_str;
	if (eventId_str !== '') { url_str += (url_str.indexOf('?') > -1 ? '&' : '?') + 'eventId=' + encodeURIComponent(eventId_str); }
	if (sessionId_str) { url_str += (url_str.indexOf('?') > -1 ? '&' : '?') + 'sessionId=' + encodeURIComponent(sessionId_str); }
	return url_str;
}

/*	Caption is three lines: event name, then when, then the session id so a printed sheet can be	*/
/*	traced back to an exact session without decoding the QR.	*/
const sessionsForJs_ary = [];
if (wantSessions_bln)
{
	for (const session_obj of chosen_ary)
	{
		sessionsForJs_ary.push({
			event: (eventTitle_str !== '' ? eventTitle_str : String(session_obj.title || '')),
			when: fmtRange_str(session_obj.timeZonedStart || session_obj.start, session_obj.timeZonedEnd || session_obj.end),
			sid: String(session_obj.id || ''),
			url: buildUrl_str(session_obj.id)
		});
	}
}

/*	=== 3. Buttons ===	*/
/*	Downloaded PNGs are named FILE_PREFIX-<eventId>[-n].png.	*/
const fileBase_str = String(cfg_obj.FILE_PREFIX || 'Attendance-QR').replace(/[^A-Za-z0-9._-]/g, '') + (eventId_str !== '' ? '-' + eventId_str.replace(/[^A-Za-z0-9._-]/g, '') : '');
const saveLabel_str = String(cfg_obj.SAVE_LABEL || 'Save PNG');
const printLabel_str = String(cfg_obj.PRINT_LABEL || 'Print / Save as PDF');
const showSave_bln = truthy_bln(cfg_obj.SHOW_SAVE_BUTTON, true);
const showPrint_bln = truthy_bln(cfg_obj.SHOW_PRINT_BUTTON, true);

const css_str = [
  '.qrp-actions{display:flex;gap:.75rem;justify-content:center;flex-wrap:wrap;padding:0 clamp(1rem,4vw,2rem) clamp(1.25rem,4vw,1.75rem);}',
  '.qrp-btn{appearance:none;-webkit-appearance:none;border:1px solid #d0d0d0;background:#fff;color:#1f1f1f;font:inherit;font-size:clamp(.85rem,2.6vw,1rem);line-height:1.2;padding:.65rem 1.25rem;border-radius:.6rem;cursor:pointer;min-height:2.75rem;}',
  '.qrp-btn:hover{background:#f4f4f5;}',
  '.qrp-btn:focus-visible{outline:.15rem solid #2563eb;outline-offset:.15rem;}',
  '.qrp-when{margin:0 0 .5rem;padding:0 clamp(1rem,4vw,2rem);}',
  '.qrp-when span{display:block;}',
  '.qrp-when-event{font-size:clamp(1rem,3.2vw,1.25rem);font-weight:700;color:#1f1f1f;line-height:1.3;}',
  '.qrp-when-time{font-size:clamp(.9rem,2.8vw,1.05rem);font-weight:600;color:#3c3c3c;margin-top:.2rem;line-height:1.3;}',
  '.qrp-when-id{font-size:clamp(.68rem,2.1vw,.78rem);font-weight:400;color:#8a8a8a;margin-top:.35rem;word-break:break-all;font-family:ui-monospace,Menlo,Consolas,monospace;}',
  '.qrp-session{padding:clamp(1.5rem,5vw,2.5rem) 0;border-top:10px solid #1f2937;}',
  '.qrp-session:first-of-type{border-top:none;padding-top:clamp(.5rem,2vw,1rem);}',
  '.qrp-session .qrp-qr{width:clamp(10.5rem,44vw,15rem);}',
  '.qrp-qr .qrp-target{width:100%;height:100%;}',
  '.qrp-qr .qrp-target canvas,.qrp-qr .qrp-target img{width:100%!important;height:100%!important;image-rendering:pixelated;display:block;}',
  '@media print{.qrp-actions{display:none !important;}.qrp-session{break-inside:avoid;border-top:none;}.qrp-session+.qrp-session{break-before:page;}}'
].join('');

let buttons_str = '';
if (showSave_bln || showPrint_bln)
{
	buttons_str = '<div class="qrp-actions">';
	if (showSave_bln) { buttons_str += '<button type="button" class="qrp-btn" id="qrp-save">' + esc_str(saveLabel_str) + '</button>'; }
	if (showPrint_bln) { buttons_str += '<button type="button" class="qrp-btn" id="qrp-print">' + esc_str(printLabel_str) + '</button>'; }
	buttons_str += '</div>';
}

const qrColor_str = '#000000';
const bgColor_str = '#ffffff';
const qrSize_int = 720;
const data_json = JSON.stringify(sessionsForJs_ary);
const logo_json = JSON.stringify(logo_str);
const fname_json = JSON.stringify(fileBase_str);

const script_str = "<scr" + "ipt>(function(){"
  + "var SESS=" + data_json + ";var LOGO=" + logo_json + ";var FNAME=" + fname_json + ";"
  + "function makeQR(el,url){try{new QRCode(el,{text:url||' ',width:" + qrSize_int + ",height:" + qrSize_int + ",colorDark:'" + qrColor_str + "',colorLight:'" + bgColor_str + "',correctLevel:QRCode.CorrectLevel.H});}catch(e){el.textContent='QR error';}}"
  + "function line(cls,txt){var s=document.createElement('span');s.className=cls;s.textContent=txt;return s;}"
  + "if(SESS&&SESS.length>0){var wrap=document.querySelector('.qrp-qrwrap');if(wrap){var card=wrap.parentNode;var anchor=wrap.nextSibling;card.removeChild(wrap);for(var i=0;i<SESS.length;i++){(function(s){var sec=document.createElement('section');sec.className='qrp-session';var cap=document.createElement('p');cap.className='qrp-when';if(s.event){cap.appendChild(line('qrp-when-event',s.event));}if(s.when){cap.appendChild(line('qrp-when-time',s.when));}if(s.sid){cap.appendChild(line('qrp-when-id','Session '+s.sid));}sec.appendChild(cap);var w=document.createElement('div');w.className='qrp-qrwrap';var q=document.createElement('div');q.className='qrp-qr';var t=document.createElement('div');t.className='qrp-target';q.appendChild(t);if(LOGO){var lg=document.createElement('img');lg.className='qrp-logo';lg.src=LOGO;lg.alt='';q.appendChild(lg);}w.appendChild(q);sec.appendChild(w);card.insertBefore(sec,anchor);makeQR(t,s.url);})(SESS[i]);}}}"
  + "var p=document.getElementById('qrp-print');if(p){p.addEventListener('click',function(){window.print();});}"
  + "function dl(u,name){var a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();}"
  + "function compose(src,qsize,lg,name){var o=document.createElement('canvas');o.width=qsize;o.height=qsize;var x=o.getContext('2d');x.fillStyle='#ffffff';x.fillRect(0,0,qsize,qsize);x.drawImage(src,0,0,qsize,qsize);var ls=lg?lg.getAttribute('src'):'';if(!ls){try{dl(o.toDataURL('image/png'),name);}catch(e){}return;}var ratio=0.22;try{if(lg.clientWidth&&lg.parentNode.clientWidth){ratio=lg.clientWidth/lg.parentNode.clientWidth;}}catch(e){}var lw=qsize*ratio,off=(qsize-lw)/2,pad=lw*0.08,rx=off-pad,rw=lw+pad*2,rr=rw*0.16;var im=new Image();im.onload=function(){x.fillStyle='#fff';x.beginPath();x.moveTo(rx+rr,rx);x.arcTo(rx+rw,rx,rx+rw,rx+rw,rr);x.arcTo(rx+rw,rx+rw,rx,rx+rw,rr);x.arcTo(rx,rx+rw,rx,rx,rr);x.arcTo(rx,rx,rx+rw,rx,rr);x.closePath();x.fill();x.drawImage(im,off,off,lw,lw);try{dl(o.toDataURL('image/png'),name);}catch(e){}};im.onerror=function(){try{dl(o.toDataURL('image/png'),name);}catch(e){}};im.src=ls;}"
  + "function exportBlock(block,idx,total){var t=block.querySelector('.qrp-target')||block.querySelector('#qrp-target');var lg=block.querySelector('.qrp-logo');var suffix=total>1?('-'+(idx+1)):'';var name=FNAME+suffix+'.png';var cv=t?t.querySelector('canvas'):null;if(cv){compose(cv,cv.width||720,lg,name);return;}var ig=t?t.querySelector('img'):null;if(ig){var t2=new Image();t2.onload=function(){compose(t2,t2.naturalWidth||720,lg,name);};t2.onerror=function(){};t2.src=ig.src;}}"
  + "function run(){var blocks=document.querySelectorAll('.qrp-qr');if(!blocks.length){alert('Could not find the QR to export.');return;}for(var i=0;i<blocks.length;i++){exportBlock(blocks[i],i,blocks.length);}}"
  + "var s=document.getElementById('qrp-save');if(s){s.addEventListener('click',run);}"
  + "})();</scr" + "ipt>";

function swapTag_str(htmlIn_str, openTag_str, closeTag_str, newInner_str) { const i_int = htmlIn_str.indexOf(openTag_str); if (i_int < 0) { return htmlIn_str; } const j_int = htmlIn_str.indexOf(closeTag_str, i_int + openTag_str.length); if (j_int < 0) { return htmlIn_str; } return htmlIn_str.slice(0, i_int + openTag_str.length) + newInner_str + htmlIn_str.slice(j_int); }

if (html_str.indexOf('</style>') > -1) { html_str = html_str.replace('</style>', css_str + '</style>'); } else { html_str = html_str.replace('</head>', '<style>' + css_str + '</style></head>'); }
if (buttons_str !== '') { if (html_str.indexOf('</main>') > -1) { html_str = html_str.replace('</main>', buttons_str + '</main>'); } else { html_str = html_str.replace('</body>', buttons_str + '</body>'); } }
html_str = html_str.replace('</body>', script_str + '</body>');
if (eventTitle_str !== '') { html_str = swapTag_str(html_str, '<h1 class="qrp-title">', '</h1>', esc_str(eventTitle_str)); html_str = swapTag_str(html_str, '<title>', '</title>', esc_str(eventTitle_str)); }

return [{ json: Object.assign({}, $json, { html: html_str, mode: mode_str, sessionCount: sessionsForJs_ary.length }) }];
